    "id": "med_1888",
    "name_en": "Ciprofloxacin 0.3% + Dexamethasone 0.1% E/E prep",
    "generic": "Ciprofloxacin 0.3% + Dexamethasone 0.1% E/E prep",
    "category": "other",
