    "id": "med_2224",
    "name_en": "Phenoxymethyl Penicillin",
    "generic": "Phenoxymethyl Penicillin",
    "category": "other",
    "category_bn": "কান ও নাক-কান-গলা",
    "icon": "👂",
    "target_organ": "Ears & ENT / কান ও নাক-কান-গলা",
